SELECT *, sum(union_table.income) AS incomeSum, sum(union_table.income_without_tax) AS incomeWithoutTaxSum FROM ( SELECT income.id as id, income.receipt_id AS receiptId, client.id AS clientId, receipt.receipt_code AS receiptCode, income.contract_id AS contractId, income.income_date AS incomeDate, base.proj_name AS projName, base.contract_code AS contractCode, base.actual_lease_date AS actualLeaseDate, client.client_name AS clientName, base.lease_type AS leaseType, base.biz_type AS bizType, income.income, income.income_without_tax FROM contract_income_sharing income LEFT JOIN contract_base_info base ON base.id = income.contract_id LEFT JOIN client ON client.id = base.client_id LEFT JOIN contract_receipt receipt ON income.receipt_id = receipt.id WHERE income.income_without_tax != 0 AND income.deleted = false
AND income.confirm_batch = #{req.batchNumber}
AND income.contract_id IN
#{item}
AND income.income_date <= #{req.endMonth}
AND income.income_date >= #{req.beginMonth}
AND income.receipt_id = #{req.receiptId}
UNION SELECT income.id as id, income.receipt_id AS receiptId, client.id AS clientId, receipt.receipt_code AS receiptCode, income.contract_id AS contractId, income.income_date AS incomeDate, base.proj_name AS projName, base.contract_code AS contractCode, base.actual_lease_date AS actualLeaseDate, client.client_name AS clientName, base.lease_type AS leaseType, base.biz_type AS bizType, income.income, income.income_without_tax FROM contract_income_sharing income LEFT JOIN contract_base_info base ON base.id = income.contract_id LEFT JOIN client ON client.id = base.client_id LEFT JOIN contract_receipt receipt ON income.receipt_id = receipt.id WHERE income.income_without_tax != 0 AND income.deleted = false AND income.is_confirmed = 0
AND income.confirm_batch = #{req.batchNumber}
AND income.contract_id IN
#{item}
AND income.income_date < #{req.beginMonth}
AND income.receipt_id = #{req.receiptId}
) AS union_table GROUP BY receiptId ORDER BY clientName,contractCode,actualLeaseDate

SELECT income.receipt_id, receipt.receipt_code, income.income_date, client.client_name, base.proj_name, base.contract_code, base.contract_status, base.income_confirm_type, income.income, income.income_without_tax, income.is_confirmed, income.confirm_time FROM contract_income_sharing income LEFT JOIN contract_base_info base ON base.id = income.contract_id LEFT JOIN client ON client.id = base.client_id LEFT JOIN contract_receipt receipt ON income.receipt_id = receipt.id WHERE income.deleted = FALSE AND income.receipt_id IN (
#{id}
)
AND client.id = #{req.clientId}
AND base.proj_name LIKE CONCAT('%', #{req.projName} ,'%')
AND base.contract_code LIKE CONCAT('%', #{req.contractCode}, '%')
AND receipt.receipt_code LIKE CONCAT('%', #{req.receiptCode} ,'%')
AND base.contract_status LIKE CONCAT('%', #{req.contractStatus} ,'%')

SELECT receipt.receipt_code, base.contract_code, income.income_date, income.begin_of_term_balance, income.end_of_term_balance, income.tax, income.rent, income.income, income.income_without_tax, income.daily_discount_rate, income.is_confirmed FROM contract_income_sharing income LEFT JOIN contract_base_info base ON base.id = income.contract_id LEFT JOIN client ON client.id = base.client_id LEFT JOIN contract_receipt receipt ON income.receipt_id = receipt.id WHERE income.deleted = FALSE AND income.receipt_id = #{req.receiptId}
AND income.income_date >= #{req.incomeDateFrom}
AND income.income_date <= #{req.incomeDateTo}
